from taf.rfrl.l3_call.logger.l3_call_logger import log_to_console


class Cell:
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self, cell_distname, shared_spectrum):
        self.dss_pair = None
        self.distname = cell_distname
        self.enb_pair = None
        self.id = None
        self.enb_pair_id = None
        self._configuration_id = self.distname.split("/")[-1].split("-")[-1]
        self._type = None
        self._shared_spectrum = shared_spectrum
        self._technology = ""
        self._beamforming_delay = None

    @property
    def cell_technology(self):
        """
        Returns technology of cell e.g. FDD/TDD/NB-IoT-FDD
        "technology" parameter is available only for LTE and 5G type of cells,
        for WCDMA and GSM should return None
        """
        if not self._technology:
            self._technology = self._get_cell_technology()
        return self._technology

    @property
    def cell_type(self):
        """
        Returns type of cell: nr/lte/wcdma/gsm
        """
        cell_types = {"NRCELL": "nr", "LNCEL": "lte", "WNCEL": "wcdma", "GNCEL": "gsm"}
        if not self._type:
            self._type = cell_types[self.distname.split("/")[-1].split("-")[0]]

        return self._type

    @property
    def beamforming_delay(self):
        """
        Returns beamforming delay for cell
        """
        if not self._beamforming_delay:
            self._beamforming_delay = self._get_beamforming_delay()
        return self._beamforming_delay

    def make_callable(self, delta=None):
        """
        Prepares cell to be called
        :param delta: DeltaOperator object, if provided parameters will be added
        to delta recommissioning will be performed after delta is complete.
        Defaults to None, which means that when delta is not passed, single parameter
        recommissioning will be performed immediately
        :type delta: DeltaOperator
        """
        self._make_callable(delta=delta)

    def make_uncallable(self, delta):
        """
        Makes all cells apart from the called one uncallable
        :param delta: DeltaOperator object to handle delta recommissioning
        :type delta: DeltaOperator
        """
        self._make_uncallable(delta=delta)

    def get_cell_id(self):
        """
        Returns cell ID

        :rtype: int
        """
        return self._get_cell_id()

    def get_protocol_for_pcap_verification(self):
        """
        Returns protocol used for PCAP verification

        :rtype: str
        """
        return self._get_protocol_for_pcap_verification()

    def get_ok_msgs_and_procedure_codes(self):
        """
        Returns messages that should be found in PCAP file
        after successful attach with their procedure codes

        :rtype: dict(str, int)
        """
        return self._get_ok_msgs_and_procedure_codes()

    def get_nok_msgs_and_procedure_codes(self):
        """
        Returns messages that should NOT be found in PCAP
        file after successful attach with their procedure codes

        :rtype: dict(str, int)
        """
        return self._get_nok_msgs_and_procedure_codes()

    def get_nok_structures(self):
        """
        Returns structures of messages that should NOT be found in PCAP
        file after successful attach

        :rtype: dict
        """
        return self._get_nok_structures()

    def is_iot_cell(self):
        """
        Checks if cell is a NB-IoT cell.

        :returns: True if cell is a NB-IoT cell, False otherwise.
        :rtype: bool
        """
        log_to_console("Checking if the cell you want to call is IoT cell")
        return True if self._type == "iot" else False

    def get_narrowband_iot_mode(self):
        """
        Returns mode of the NB-IoT cell, possible values are: 'inband', 'guardband', 'standalone', 'guardband-NR',
                                                              'disabled' or None.
        Narrowband IoT made is available for NB-IoT cells and NR or LTE host cells supported IoT technology.
        Method returns None when cell is not NB-IoT cell and does not support IoT cells hosting.

        :returns: narrowband IoT mode
        :rtype: str or None
        """
        return self._get_narrowband_iot_mode()

    def is_dss(self):
        """
        Checks if cell operates in DSS mode
        """
        log_to_console("Checking if the cell you want to call operates in DSS mode")
        return self._is_dss()

    def is_beamforming_activated(self):
        """
        Checks if beamforming is activated by getting value of
        actBeamforming parameter
        """
        log_to_console("Checking if the cell you want to call has beamforming activated")
        return self._is_beamforming_activated()

    def get_dss_pair(self):
        """
        Returns configuration distname of cell with which called cell is
        dynamically sharing spectrum (DSS)
        """
        return self._get_dss_pair()

    def get_number_of_super_subcells(self):
        """
        Returns number of subcells that supercell is composed of.
        """
        return self._get_number_of_super_subcells()

    def make_barred(self, delta):
        """
        Makes cell barred
        """
        self._make_barred(delta=delta)

    def make_unbarred(self, delta):
        """
        Makes cell unbarred
        """
        self._make_unbarred(delta=delta)

    def _raise_not_implemented_error(self, method_name):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            method_name))

    def _make_callable(self, delta):
        self._raise_not_implemented_error(self._make_callable.__name__)

    def _make_uncallable(self, delta):
        self._raise_not_implemented_error(self._make_uncallable.__name__)

    def _get_cell_id(self):
        self._raise_not_implemented_error(self._get_cell_id.__name__)

    def _get_protocol_for_pcap_verification(self):
        self._raise_not_implemented_error(self._get_protocol_for_pcap_verification.__name__)

    def _get_ok_msgs_and_procedure_codes(self):
        self._raise_not_implemented_error(self._get_ok_msgs_and_procedure_codes.__name__)

    def _get_nok_msgs_and_procedure_codes(self):
        self._raise_not_implemented_error(self._get_nok_msgs_and_procedure_codes.__name__)

    def _get_nok_structures(self):
        self._raise_not_implemented_error(self._get_nok_structures.__name__)

    def _get_dss_pair(self):
        self._raise_not_implemented_error(self._get_dss_pair.__name__)

    def _get_number_of_super_subcells(self):
        self._raise_not_implemented_error(self._get_number_of_super_subcells.__name__)

    def _is_beamforming_activated(self):
        self._raise_not_implemented_error(self._is_beamforming_activated.__name__)

    def _get_beamforming_delay(self):
        self._raise_not_implemented_error(self._get_beamforming_delay.__name__)

    def _get_cell_technology(self):
        self._raise_not_implemented_error(self._get_cell_technology.__name__)

    def _get_narrowband_iot_mode(self):
        self._raise_not_implemented_error(self._get_narrowband_iot_mode.__name__)

    def _is_dss(self):
        self._raise_not_implemented_error(self._is_dss.__name__)

    def _make_barred(self, delta):
        self._raise_not_implemented_error(self._make_barred.__name__)

    def _make_unbarred(self, delta):
        self._raise_not_implemented_error(self._make_unbarred.__name__)
